css:
.spines-loader {
  --dur: 1.4s;
  --gold-foil: linear-gradient(
    90deg,
    #b38728,
    #fbf5b7 45%,
    #daae51 70%,
    #aa771c
  );

  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 8px;
  height: 106px;
}

/* Individual Book Spines */
.spines-loader__book,
.spines-loader b {
  flex: none;
  width: 18px;
  height: var(--hh, 60px);
  border-radius: 3px 3px 2px 2px;
  position: relative;
  transform-origin: 50% 100%;

  /* 3D Cylindrical Spine Shading & Embossed Texture */
  background: repeating-linear-gradient(
      180deg,
      transparent 0,
      transparent 15px,
      rgba(0, 0, 0, 0.25) 16px,
      rgba(255, 255, 255, 0.2) 17px,
      rgba(0, 0, 0, 0.15) 18px,
      transparent 19px
    ),
    linear-gradient(
      90deg,
      rgba(255, 255, 255, 0.3) 0%,
      rgba(255, 255, 255, 0.45) 14%,
      transparent 32%,
      rgba(0, 0, 0, 0.08) 60%,
      rgba(0, 0, 0, 0.38) 92%,
      rgba(0, 0, 0, 0.55) 100%
    ),
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.15) 0%,
      transparent 15%,
      rgba(0, 0, 0, 0.15) 85%,
      rgba(0, 0, 0, 0.35) 100%
    ),
    var(--c, #c9364a);

  box-shadow:
    inset 1px 0 1px rgba(255, 255, 255, 0.35),
    inset -1px 0 2px rgba(0, 0, 0, 0.45),
    inset 0 1px 1px rgba(255, 255, 255, 0.35),
    0 4px 8px rgba(0, 0, 0, 0.3);

  animation: spines-wave var(--dur) ease-in-out infinite;
  animation-delay: calc(var(--i, 0) * var(--dur) * 0.1);
  will-change: transform, box-shadow;
}

/* Gold Foil Stamped Band (Top) */
.spines-loader__book::before,
.spines-loader b::before {
  content: "";
  position: absolute;
  left: 2px;
  right: 2px;
  top: 10px;
  height: 4px;
  background: var(--gold-foil);
  border-radius: 0.5px;
  box-shadow:
    0 1px 0 rgba(0, 0, 0, 0.35),
    0 -1px 0 rgba(255, 255, 255, 0.25),
    0 0 3px rgba(245, 208, 97, 0.35);
  opacity: 0.9;
  animation: spines-foil-gleam var(--dur) ease-in-out infinite;
  animation-delay: calc(var(--i, 0) * var(--dur) * 0.1);
}

/* Gold Foil Stamped Band (Bottom) */
.spines-loader__book::after,
.spines-loader b::after {
  content: "";
  position: absolute;
  left: 2px;
  right: 2px;
  bottom: 8px;
  height: 3px;
  background: var(--gold-foil);
  border-radius: 0.5px;
  box-shadow:
    0 1px 0 rgba(0, 0, 0, 0.35),
    0 -1px 0 rgba(255, 255, 255, 0.2),
    0 0 2px rgba(245, 208, 97, 0.3);
  opacity: 0.85;
  animation: spines-foil-gleam var(--dur) ease-in-out infinite;
  animation-delay: calc(var(--i, 0) * var(--dur) * 0.1);
}

/* Ultra-Smooth Wave Jump Animation */
@keyframes spines-wave {
  0%,
  100% {
    transform: translateY(0) scaleY(1);
    box-shadow:
      inset 1px 0 1px rgba(255, 255, 255, 0.35),
      inset -1px 0 2px rgba(0, 0, 0, 0.45),
      inset 0 1px 1px rgba(255, 255, 255, 0.35),
      0 4px 8px rgba(0, 0, 0, 0.3);
  }
  50% {
    transform: translateY(-20px) scaleY(1.06);
    box-shadow:
      inset 1px 0 1px rgba(255, 255, 255, 0.35),
      inset -1px 0 2px rgba(0, 0, 0, 0.45),
      inset 0 1px 1px rgba(255, 255, 255, 0.35),
      0 20px 14px rgba(0, 0, 0, 0.12);
  }
}

/* Soft Gold Foil Gleam */
@keyframes spines-foil-gleam {
  0%,
  100% {
    filter: brightness(1);
  }
  50% {
    filter: brightness(1.35) drop-shadow(0 0 3px #fff5c0);
  }
}
